head.b:skin:
/*
 * AI ForgeLab - Updated Production Theme v2.1
 * Niche: Artificial Intelligence
 */

/* --- THEME CONTROL PANEL --- */
/* <Group description="AI ForgeLab Colors" title="Brand Colors">
    <Variable name="bg.main" description="Main Background" type="color" default="#0B0F19"/>
    <Variable name="bg.secondary" description="Secondary Background" type="color" default="#111827"/>
    <Variable name="accent.primary" description="Primary Accent (Neon)" type="color" default="#00F5A0"/>
    <Variable name="accent.secondary" description="Secondary Accent (Indigo)" type="color" default="#4F46E5"/>
    <Variable name="text.main" description="Primary Text" type="color" default="#E5E7EB"/>
    <Variable name="text.muted" description="Muted Text" type="color" default="#9CA3AF"/>
</Group> */

:root {
    --bg-main: $(bg.main);
    --bg-secondary: $(bg.secondary);
    --accent-primary: $(accent.primary);
    --accent-secondary: $(accent.secondary);
    --text-main: $(text.main);
    --text-muted: $(text.muted);
    --glass: rgba(255, 255, 255, 0.03);
    --glass-border: rgba(255, 255, 255, 0.08);
    --neon-glow: 0 0 15px rgba(0, 245, 160, 0.3);
    --transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}

/* Global Reset */
* { box-sizing: border-box; margin: 0; padding: 0; }
body {
    background-color: var(--bg-main);
    color: var(--text-main);
    font-family: 'Inter', sans-serif;
    line-height: 1.6;
    overflow-x: hidden;
    -webkit-font-smoothing: antialiased;
}

/* Animations */
@keyframes fadeIn { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: translateY(0); } }
@keyframes meshGradient {
    0% { background-position: 0% 50%; }
    50% { background-position: 100% 50%; }
    100% { background-position: 0% 50%; }
}
@keyframes promptGlow {
    0% { box-shadow: 0 0 10px rgba(0, 245, 160, 0.2); border-color: var(--glass-border); }
    50% { box-shadow: 0 0 30px rgba(0, 245, 160, 0.5); border-color: var(--accent-primary); }
    100% { box-shadow: 0 0 10px rgba(0, 245, 160, 0.2); border-color: var(--glass-border); }
}

.reveal { opacity: 0; transition: var(--transition); }
.reveal.active { opacity: 1; transform: translateY(0); }

/* Sticky Header */
header {
    position: fixed; top: 0; width: 100%; z-index: 1000;
    background: rgba(11, 15, 25, 0.8);
    backdrop-filter: blur(12px);
    border-bottom: 1px solid var(--glass-border);
    transition: var(--transition);
}
header.scrolled { padding: 5px 0; background: rgba(11, 15, 25, 0.95); }

.nav-container {
    max-width: 1300px; margin: 0 auto; padding: 10px 25px;
    display: flex; justify-content: space-between; align-items: center;
    position: relative;
}

.logo-wrap {
    display: flex; align-items: center; text-decoration: none; gap: 12px;
    white-space: nowrap; flex-shrink: 0;
}
.logo-text {
    font-weight: 800; font-size: 1.6rem; color: #fff; letter-spacing: -1px;
    line-height: 1;
}
.logo-text span { color: var(--accent-primary); }

/* Navigation & Hamburger */
nav { display: none; } /* Default hide traditional nav */

.hamburger {
    width: 30px; height: 20px; position: relative; cursor: pointer;
    display: flex; flex-direction: column; justify-content: space-between;
    z-index: 1001;
}
.hamburger span {
    display: block; width: 100%; height: 2px; background: var(--text-main);
    border-radius: 2px; transition: var(--transition);
}
.hamburger.active span:nth-child(1) { transform: translateY(9px) rotate(45deg); }
.hamburger.active span:nth-child(2) { opacity: 0; }
.hamburger.active span:nth-child(3) { transform: translateY(-9px) rotate(-45deg); }

.mobile-menu {
    position: fixed; top: 0; right: -100%; width: 300px; height: 100vh;
    background: var(--bg-secondary); border-left: 1px solid var(--glass-border);
    padding: 100px 40px; transition: var(--transition); z-index: 1000;
    display: flex; flex-direction: column; gap: 20px;
    box-shadow: -10px 0 30px rgba(0,0,0,0.5);
}
.mobile-menu.active { right: 0; }
.mobile-menu a {
    color: var(--text-main); text-decoration: none; font-size: 1.2rem;
    font-weight: 600; transition: var(--transition);
}
.mobile-menu a:hover { color: var(--accent-primary); padding-left: 10px; }

/* Desktop Nav for larger screens */
@media (min-width: 1025px) {
    nav { display: block; }
    nav ul { display: flex; list-style: none; gap: 30px; }
    nav a { color: var(--text-main); text-decoration: none; font-size: 0.95rem; font-weight: 600; transition: var(--transition); opacity: 0.8; }
    nav a:hover { color: var(--accent-primary); opacity: 1; }
    .hamburger { display: none; }
}

/* Reading Progress */
.progress-container { position: fixed; top: 0; width: 100%; height: 3px; z-index: 1001; }
.progress-bar { height: 100%; background: linear-gradient(to right, var(--accent-secondary), var(--accent-primary)); width: 0%; }

/* Hero Section */
.hero {
    height: 85vh; min-height: 600px;
    display: flex; align-items: center; justify-content: center;
    text-align: center; position: relative; overflow: hidden;
    background: radial-gradient(circle at 50% 50%, rgba(79, 70, 229, 0.15), transparent 70%);
}
.hero::before {
    content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0;
    background: linear-gradient(-45deg, #0B0F19, #111827, #0B0F19, #1a1a2e);
    background-size: 400% 400%; animation: meshGradient 15s ease infinite;
    z-index: -1;
}
.hero-content { max-width: 800px; padding: 0 20px; z-index: 2; }
.hero h1 { font-size: clamp(2.5rem, 8vw, 4.5rem); font-weight: 800; line-height: 1.1; margin-bottom: 20px; }
.hero h1 span { color: var(--accent-primary); text-shadow: var(--neon-glow); }
.hero p { font-size: 1.2rem; color: var(--text-muted); margin-bottom: 35px; }

/* Buttons */
.btn {
    display: inline-flex; align-items: center; justify-content: center; gap: 10px;
    padding: 12px 28px; border-radius: 12px; font-weight: 700;
    text-decoration: none; transition: var(--transition); cursor: pointer; border: none;
    font-size: 0.95rem; line-height: 1.2;
}
.btn-primary {
    background: var(--accent-primary); color: var(--bg-main);
    box-shadow: 0 4px 15px rgba(0, 245, 160, 0.2);
}
.btn-primary:hover { transform: translateY(-2px); box-shadow: 0 8px 25px rgba(0, 245, 160, 0.4); }

.btn-glass {
    background: var(--glass); color: #fff;
    border: 1px solid var(--glass-border); backdrop-filter: blur(8px);
}
.btn-glass:hover { background: rgba(255,255,255,0.08); border-color: var(--accent-primary); transform: translateY(-2px); }

/* Card System */
.section-title {
    font-size: clamp(1.5rem, 5vw, 2.2rem); font-weight: 800; margin-bottom: 40px;
    display: flex; align-items: center; gap: 15px; line-height: 1.2;
}
.section-title::after { content: ''; flex-grow: 1; height: 1px; background: var(--glass-border); }

.card-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 30px; margin-bottom: 80px;
}

@media (max-width: 1024px) {
    .card-grid { grid-template-columns: repeat(2, 1fr); gap: 20px; }
}
@media (max-width: 600px) {
    .card-grid { grid-template-columns: 1fr; gap: 25px; }
}

.post-card {
    background: var(--bg-secondary);
    border-radius: 24px; border: 1px solid var(--glass-border);
    overflow: hidden; text-decoration: none; transition: var(--transition);
    display: flex; flex-direction: column; position: relative;
    height: 100%;
}
.post-card:hover {
    transform: translateY(-8px);
    border-color: var(--accent-primary);
    box-shadow: 0 20px 40px rgba(0,0,0,0.3);
}
.card-img {
    width: 100%; aspect-ratio: 16 / 9; object-fit: cover;
    transition: var(--transition); filter: brightness(0.9);
    display: block; background: var(--bg-main);
}
.card-placeholder {
    width: 100%; aspect-ratio: 16 / 9;
    background: var(--bg-main);
    display: flex; align-items: center; justify-content: center;
    color: var(--accent-primary); opacity: 0.5;
}
.post-card:hover .card-img { transform: scale(1.05); filter: brightness(1.1); }

.card-body { padding: 30px; flex-grow: 1; display: flex; flex-direction: column; }
.card-tag { font-size: 0.75rem; font-weight: 800; color: var(--accent-primary); text-transform: uppercase; margin-bottom: 12px; letter-spacing: 1px; }
.card-title {
    font-size: 1.1rem; font-weight: 700; color: #fff; margin-bottom: 15px;
    line-height: 1.4; word-wrap: break-word; overflow: visible;
    white-space: normal; width: 100%; padding: 0 5px;
}
.card-excerpt {
    font-size: 0.95rem; color: var(--text-muted); margin-bottom: 25px;
    display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical;
    overflow: hidden; line-height: 1.6;
}
.card-footer {
    margin-top: auto; padding-top: 20px; border-top: 1px solid var(--glass-border);
    display: flex; align-items: center; justify-content: space-between;
}
.read-more { font-size: 0.9rem; font-weight: 700; color: var(--accent-primary); }
.blog-pager { display: flex; justify-content: center; gap: 20px; margin: 40px 0; }

/* Prompts Specifics */
.prompt-box { background: #070a11; border: 1px solid var(--glass-border); border-radius: 12px; padding: 20px; margin: 15px 0; position: relative; }
.prompt-text-content { font-family: 'Courier New', monospace; font-size: 0.9rem; color: var(--accent-primary); word-break: break-all; }
.copy-btn { position: absolute; top: 15px; right: 15px; background: var(--accent-primary); color: var(--bg-main); border: none; padding: 5px 12px; border-radius: 8px; font-size: 0.75rem; font-weight: 700; cursor: pointer; }
.generator-btns { display: flex; gap: 10px; margin-top: 15px; flex-wrap: wrap; }
.gen-btn { background: var(--glass); border: 1px solid var(--glass-border); color: #fff; text-decoration: none; padding: 6px 12px; border-radius: 8px; font-size: 0.75rem; transition: 0.3s; }
.gen-btn:hover { background: var(--accent-primary); color: var(--bg-main); }

.prompt-of-the-day { grid-column: 1 / -1; animation: promptGlow 4s infinite; }
.prompt-of-the-day .card-title { font-size: 2.2rem; }

/* Single Post & Page Styles */
.post-container {
    background: var(--bg-secondary);
    border-radius: 24px;
    padding: 40px;
    border: 1px solid var(--glass-border);
    margin-bottom: 40px;
    animation: fadeIn 0.8s ease;
    direction: ltr !important;
    text-align: left !important;
}
.post-header { margin-bottom: 30px; border-bottom: 1px solid var(--glass-border); padding-bottom: 20px; }
.post-header h1 {
    font-size: clamp(1.2rem, 3.5vw, 1.8rem); margin: 15px 0; line-height: 1.3;
    overflow-wrap: break-word; word-wrap: break-word; word-break: break-word;
    white-space: normal; overflow: visible; width: 100%; display: block;
}
.post-meta { font-size: 0.85rem; color: var(--text-muted); margin-bottom: 25px; }
.post-featured-img {
    display: block; width: auto; max-width: 85%; max-height: 450px;
    object-fit: contain; border-radius: 16px; margin: 0 auto 40px;
    border: 1px solid var(--glass-border);
}
.post-body { font-size: 1.05rem; line-height: 1.8; color: var(--text-main); }
.post-body img { max-width: 100%; height: auto; display: block; margin: 30px auto; border-radius: 12px; }
.social-share { margin-top: 50px; padding-top: 30px; border-top: 1px solid var(--glass-border); }

/* Responsive Overrides */
@media (max-width: 768px) {
    .hero { height: auto; padding: 120px 20px 80px; }
    .hero h1 { font-size: 2.8rem; }
    .main-wrapper { flex-direction: column; padding: 0 20px; }
    .sidebar { width: 100%; margin-top: 40px; }
    .post-container { padding: 25px; border-radius: 16px; }
}

@media (max-width: 480px) {
    .logo-text { font-size: 1.3rem; }
    .hero h1 { font-size: 2.2rem; }
    .btn { width: 100%; }
    .hero-content div { flex-direction: column; }
    .card-title { font-size: 1rem; -webkit-line-clamp: 3; display: -webkit-box; -webkit-box-orient: vertical; overflow: hidden; }
    .post-header h1 { font-size: 1.25rem; }
}

/* Sidebar & Footer */
.main-wrapper {
    max-width: 1300px; margin: 140px auto 40px; padding: 0 25px;
    display: flex; gap: 40px; position: relative; z-index: 1;
}
#main-content { flex-grow: 1; min-width: 0; }
.sidebar { width: 320px; flex-shrink: 0; }

@media (max-width: 1024px) {
    .main-wrapper { flex-direction: column; margin-top: 120px; }
    .sidebar { width: 100%; margin-top: 20px; }
}

.sidebar-widget { background: var(--bg-secondary); border-radius: 20px; padding: 25px; margin-bottom: 30px; border: 1px solid var(--glass-border); }
.widget-title { font-size: 1.1rem; font-weight: 700; margin-bottom: 20px; color: var(--accent-primary); }
footer {
    background: #070a11; border-top: 1px solid var(--glass-border);
    padding: 60px 25px; text-align: center;
}
.footer-links-minimal {
    display: flex; justify-content: center; gap: 30px; flex-wrap: wrap;
    margin-bottom: 30px; list-style: none;
}
.footer-links-minimal a {
    color: var(--text-muted); text-decoration: none; font-size: 0.9rem;
    transition: var(--transition);
}
.footer-links-minimal a:hover { color: var(--accent-primary); }
.footer-bottom { color: var(--text-muted); font-size: 0.85rem; }

.back-to-top { position: fixed; bottom: 30px; right: 30px; background: var(--accent-primary); color: var(--bg-main); width: 45px; height: 45px; border-radius: 50%; display: flex; align-items: center; justify-content: center; cursor: pointer; z-index: 100; transition: var(--transition); opacity: 0; visibility: hidden; }
.back-to-top.show { opacity: 1; visibility: visible; }
.sound-toggle { position: fixed; bottom: 30px; left: 30px; background: var(--bg-secondary); border: 1px solid var(--glass-border); width: 45px; height: 45px; border-radius: 50%; display: flex; align-items: center; justify-content: center; cursor: pointer; z-index: 100; }

body.script:
//
    const config = { soundEnabled: false, postsPerSection: 3 };

    // Sound Engine
    const AudioContext = window.AudioContext || window.webkitAudioContext;
    const audioCtx = new AudioContext();
    function playSound(freq, type, dur) {
        if (!config.soundEnabled) return;
        if (audioCtx.state === 'suspended') audioCtx.resume();
        const osc = audioCtx.createOscillator();
        const gain = audioCtx.createGain();
        osc.type = type; osc.frequency.setValueAtTime(freq, audioCtx.currentTime);
        gain.gain.setValueAtTime(0.1, audioCtx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.0001, audioCtx.currentTime + dur);
        osc.connect(gain); gain.connect(audioCtx.destination);
        osc.start(); osc.stop(audioCtx.currentTime + dur);
    }

    window.onscroll = function() {
        let winScroll = document.body.scrollTop || document.documentElement.scrollTop;
        let height = document.documentElement.scrollHeight - document.documentElement.clientHeight;
        document.getElementById("scrollBar").style.width = (winScroll / height) * 100 + "%";
        document.getElementById("mainHeader").classList.toggle("scrolled", winScroll > 50);
        document.getElementById("backToTop").classList.toggle("show", winScroll > 500);
        document.querySelectorAll('.reveal').forEach(el => { if (el.getBoundingClientRect().top < window.innerHeight - 100) el.classList.add('active'); });
    };

    document.getElementById("backToTop").onclick = () => {
        playSound(440, 'sine', 0.2);
        window.scrollTo({top: 0});
    };

    const menuBtn = document.getElementById("menuBtn");
    const mobileMenu = document.getElementById("mobileMenu");
    if (menuBtn && mobileMenu) {
        menuBtn.onclick = () => {
            menuBtn.classList.toggle("active");
            mobileMenu.classList.toggle("active");
            playSound(300, 'triangle', 0.05);
        };
        // Close menu when clicking outside or on a link
        document.addEventListener('click', (e) => {
            if (!menuBtn.contains(e.target) && !mobileMenu.contains(e.target)) {
                menuBtn.classList.remove("active");
                mobileMenu.classList.remove("active");
            }
        });
    }

    document.getElementById("soundToggle").onclick = function() {
        config.soundEnabled = !config.soundEnabled;
        this.style.color = config.soundEnabled ? 'var(--accent-primary)' : 'var(--text-muted)';
        if (config.soundEnabled) playSound(880, 'square', 0.1);
    };

    function copyText(btn) {
        const text = btn.nextElementSibling.innerText;
        navigator.clipboard.writeText(text).then(() => {
            const old = btn.innerText; btn.innerText = 'Copied!';
            playSound(660, 'sine', 0.1);
            setTimeout(() => btn.innerText = old, 2000);
        });
    }

    function share(platform) {
        const url = encodeURIComponent(window.location.href);
        const title = encodeURIComponent(document.title);
        let shareUrl = '';
        if (platform === 'twitter') shareUrl = `https://twitter.com/intent/tweet?url=${url}&text=${title}`;
        else if (platform === 'facebook') shareUrl = `https://www.facebook.com/sharer/sharer.php?u=${url}`;
        else if (platform === 'linkedin') shareUrl = `https://www.linkedin.com/sharing/share-offsite/?url=${url}`;
        window.open(shareUrl, '_blank', 'width=600,height=400');
    }

    // Reading Time Calculation
    function initPostFeatures() {
        const postBody = document.getElementById('postBody');
        if (postBody && document.getElementById('readingTime')) {
            const text = postBody.innerText;
            const wpm = 225;
            const words = text.trim().split(/\s+/).length;
            const time = Math.ceil(words / wpm);
            document.getElementById('readingTime').innerText = time + ' min read';
        }
    }
    window.addEventListener('DOMContentLoaded', initPostFeatures);

    document.addEventListener('mouseover', e => {
        if (e.target.closest('a, button, .post-card')) playSound(150, 'triangle', 0.05);
    });

//
